/**
 * The card fields are only checked by the simulated gateway and never stored
 * or logged (SPEC AS-9). attemptId is generated by the client once per payment
 * attempt and reused on retries, so an attempt is never charged twice
 * (AC-KAN-22-09). expectedPriceInCents is the price the visitor saw
 * (AC-KAN-22-08).
 */
export interface PayPlanCheckoutPayload {
  readonly attemptId: string;
  readonly cardCvc: string;
  readonly cardExpiry: string;
  readonly cardNumber: string;
  readonly cardholderName: string;
  readonly email: string;
  readonly expectedPriceInCents: number;
  readonly language: string;
  readonly planId: string;
  readonly recaptchaToken: string;
  readonly termsAccepted: boolean;
}

export interface PayPlanCheckoutResponse {
  /** The normalized checkout email, shown on the confirmation page (AC-KAN-22-02). */
  readonly email: string;
}
